import {parseCatalogue,selectBookRange} from './book-import.js';
const $=id=>document.getElementById(id);let books=[],selection=null,requestId=0;
function status(message,error=false){$('bookStatus').textContent=message;$('bookStatus').classList.toggle('error',error);}
function preview(){selection=null;$('applyBook').disabled=true;const book=books[Number($('bookSelect').value)];if(!book)return;try{selection=selectBookRange(book,Number($('bookFrom').value),Number($('bookTo').value));$('applyBook').disabled=false;status(`${selection.count}語をセットできます`+(selection.count!==selection.sourceCount?'（同じ英単語の重複は1語として扱います）':''));$('bookPreview').textContent=book.words.filter(w=>w.id>=selection.from&&w.id<=selection.to).slice(0,4).map(w=>`${w.id}. ${w.word} ＝ ${w.meaning}`).join('\n');}catch(e){$('bookPreview').textContent='';status(e.message,true);}}
function populate(){$('bookSelect').replaceChildren();books.forEach((book,i)=>{const option=document.createElement('option');option.value=i;option.textContent=book.label+'（'+book.words.length+'項目）';$('bookSelect').append(option);});$('bookFields').hidden=false;$('bookSelect').value='0';choose();}
function choose(){const b=books[Number($('bookSelect').value)];if(!b)return;$('bookFrom').value=b.words[0].id;$('bookTo').value=b.words[Math.min(19,b.words.length-1)].id;preview();}
$('bookFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;const request=++requestId;$('applyBook').disabled=true;selection=null;books=[];$('bookFields').hidden=true;try{if(file.size>20*1024*1024)throw Error('20MB以下のJSONファイルを選んでください。');const text=await file.text();if(request!==requestId)return;books=parseCatalogue(JSON.parse(text));populate();}catch(e){if(request!==requestId)return;status(e instanceof SyntaxError?'JSONを読み取れません。単語帳の書き出しファイルを選んでください。':e.message,true);}finally{if(request===requestId)e.target.value='';}});
$('bookSelect').addEventListener('change',choose);for(const id of ['bookFrom','bookTo'])$(id).addEventListener('input',preview);
$('applyBook').onclick=()=>{if(!selection)return;const input=$('words');input.value=selection.raw;input.dispatchEvent(new Event('input',{bubbles:true}));$('saveWords').click();if(!$('error').textContent){status(selection.label+' No.'+selection.from+'〜'+selection.to+' の'+selection.count+'語をセットしました。');$('editWords').scrollIntoView({behavior:'smooth',block:'center'});}};

async function loadConnected(){const request=++requestId;$('loadBooks').disabled=true;status('単語帳を読み込み中…');try{const response=await fetch('private-wordbooks/catalogue.json',{credentials:'same-origin',cache:'no-cache'});if(!response.ok)throw Error('専用サイトの単語帳を取得できません。JSONファイルからも取り込めます。');const data=await response.json();if(request!==requestId)return;books=parseCatalogue(data);populate();$('bookSource').textContent='GitHubから取得済み · '+data.generatedAt+'時点（自動同期なし）';}catch(e){if(request===requestId)status(e.message,true);}finally{$('loadBooks').disabled=false;}}
$('loadBooks').onclick=loadConnected;
loadConnected();

$('chooseBook').onclick=()=>{$('bookPicker').open=true;$('bookPicker').scrollIntoView({behavior:'smooth',block:'start'});};
